import { runComparison } from './lib/core.mjs';
import { reductionRatio } from './lib/analytics.mjs';
const app = document.querySelector('#app');
const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;' }[c]));
const catalogue = await fetch('./data/catalog.json').then(r => { if (!r.ok) throw new Error('Catalogue unavailable'); return r.json(); }).catch(() => ({ components: [], inventoryGaps: ['Catalogue failed to load'] }));
const evidence = await fetch('./data/results.json').then(r => r.ok ? r.json() : null).catch(() => null);
const publicConfig = await fetch('./data/publication.json').then(r => r.ok ? r.json() : null).catch(() => null);
const components = catalogue.components;
const flagship = [
  ['C02','01 / CONTEXT','Sparse context','Keep exact history addressable while carrying only the evidence a task needs.'],
  ['C07','02 / GENERATION','Anchored generation','Define typed boundaries for parallel work and verify the assembled result.'],
  ['C11','03 / LANGUAGE','Headspace','Investigate complementary language profiles with matched vocabulary and compute.'],
  ['C04','04 / ORCHESTRATION','Context routing','Separate which evidence an agent receives from which model performs the work.']
];
const tabs = ['Overview','Lab','Architecture','Tests','Benchmarks','Failure Cases','Documentation'];
const definition = pairs => `<dl>${pairs.map(([label, value]) => `<dt>${escape(label)}</dt><dd>${escape(value || 'Unavailable')}</dd>`).join('')}</dl>`;
const badge = c => `<span class="badge ${c.implementationStatus === 'reference_slice' ? '' : 'research'}">${c.implementationStatus === 'reference_slice' ? 'Reference slice' : 'Design / reported history'}</span>`;
const testsFor = c => evidence?.coverage?.find(x => x.componentId === c.id);
const metricRows = c => c.metrics.map(metric => `<tr><td>${escape(metric)}</td><td>Unavailable</td><td>Unavailable</td><td>Matched component/backend run required</td></tr>`).join('');
function home() {
  app.innerHTML = `<section class="hero"><div><div class="eyebrow">NOVACANENUMB / ARCHITECTURE PROGRAMME</div><h1>More deliberate<br>AI systems.</h1><p class="lead">Designs for context, generation and agent workflows. Explore each mechanism, its ownership boundaries, and the evidence needed to evaluate it.</p><div class="actions"><a class="button" href="#/lab">Run the context lab</a><a class="button" href="#/evidence">Inspect the evidence</a></div></div><div class="pipeline" aria-label="Integrated architecture path">${[['01','C03','Exact archive + sparse packet'],['02','C06','Sealed anchors + context allocation'],['03','C07','Bounded candidate generation'],['04','C21','Evidence + semantic validation'],['05','C27','Accounting + reproducible release']].map(([n,id,title]) => `<a href="#/component/${id}"><span>${n}</span><b>${title}</b></a>`).join('')}<p class="muted">These branches are alternatives. Small tasks do not need every component.</p></div></section><section class="section"><div class="eyebrow">FOUR FLAGSHIP FAMILIES</div><div class="grid">${flagship.map(([id,n,title,text]) => `<article class="flag"><div class="number">${n}</div><a href="#/component/${id}"><h2>${title}</h2></a><p>${text}</p><a href="#/component/${id}">Explore the design</a></article>`).join('')}</div></section><section class="section"><div class="heading"><div><div class="eyebrow">THE COMPONENT ATLAS</div><h2>28 components. Explicit boundaries.</h2></div><label>Find a component<input type="search" id="search" placeholder="Context, GTFL, Headspace…"></label></div><div class="notice">The catalogue records the full design programme. This release implements a bounded sparse-context and analytics reference slice. Historical implementation reports and native research retain their own status.</div><div class="catalog" id="catalog"></div></section>`;
  const draw = query => document.querySelector('#catalog').innerHTML = components.filter(c => `${c.id} ${c.title} ${c.layer} ${c.purpose}`.toLowerCase().includes(query)).map(c => `<article class="component"><div class="number">${c.id}</div><div><a href="#/component/${c.id}"><h3>${escape(c.title)}</h3></a>${badge(c)}<p>${escape(c.purpose)}</p></div></article>`).join('');
  draw(''); document.querySelector('#search').oninput = e => draw(e.target.value.toLowerCase());
}
function component(c, tab = 'Overview') {
  if (!c) { app.innerHTML = '<h1>Component unavailable</h1><a href="#/">Return to the atlas</a>'; return; }
  const coverage = testsFor(c);
  const content = {
    Overview: definition([['Purpose',c.purpose],['Intended improvement',c.improvement],['Historical source status',c.sourceStatus],['Current implementation',c.implementationStatus],['Claim boundary',c.claimBoundary]]),
    Lab: ['C02','C03','C04','C27'].includes(c.id) ? `<p>${escape(c.lab)}</p><a class="button" href="#/lab">Open the shared reference lab</a><p class="notice">The lab executes context packets and comparison accounting. It does not complete this component's full contract or call a model.</p>` : `<p>${escape(c.lab)}</p><div class="notice">This mechanism is specified but unavailable in the current release. The proposed lab is described here; no simulated native or provider implementation is substituted.</div>`,
    Architecture: definition([['Architectural layer',c.layer],['Core mechanism',c.design],['Dependencies',c.dependencies.join(', ') || 'No portfolio dependency'],['First standalone deliverable',c.firstDeliverable]]) + `<p>${c.dependencies.map(id => `<a href="#/component/${id}">${id}</a>`).join(' · ')}</p>`,
    Tests: `<p>Acceptance requirements and current evidence are separate.</p><div class="scroll"><table><thead><tr><th>ID</th><th>Requirement</th><th>Current result</th></tr></thead><tbody>${c.acceptance.map(t => `<tr><td>${t.id}</td><td>${escape(t.text)}</td><td>${escape(coverage?.acceptance?.find(a => a.id === t.id)?.status ?? 'NOT_RUN')}</td></tr>`).join('')}</tbody></table></div><p>Reproduce available tests: <code>npm test</code>. Coverage: ${escape(coverage?.mechanismStatus ?? 'Unavailable')}.</p>`,
    Benchmarks: `<p>Specified endpoints need complete, matched baseline and candidate runs. None of the numbers in this table is inferred from a short prompt or a fixture animation.</p><div class="scroll"><table><thead><tr><th>Metric</th><th>Default model</th><th>Component</th><th>Evidence gate</th></tr></thead><tbody>${metricRows(c)}</tbody></table></div><a href="#/evidence">Inspect fixture comparisons and statistical arithmetic</a>`,
    'Failure Cases': `<h3>Failure conditions in the contract</h3><ul>${c.acceptance.map(t => `<li>${escape(t.text)}</li>`).join('')}</ul><p class="notice">An acceptance scenario describes a required behavior. Only an executed test linked in the Tests view establishes evidence for that path. Missing native support, stale scope, overflow and unresolved claims must stay visible.</p>`,
    Documentation: definition([['Contribution', 'User-authored design programme; AI-assisted reference implementation and presentation. New elaborations are not reconstructions of missing historical code.'],['Source IDs',c.sources.join(', ')],['Derived specification lineage',`${c.lineage.document}, lines ${c.lineage.startLine}–${c.lineage.endLine}; ${c.lineage.specificationId}`],['Original implementation inspection',c.lineage.originalSourceInspection],['Inventory gaps',catalogue.inventoryGaps.join('; ')]]) + '<a href="./data/catalog.json" download>Download the sanitized catalogue</a>'
  };
  app.innerHTML = `<section class="section"><a href="#/">Component atlas</a><p class="eyebrow">${c.id} / ${escape(c.layer)}</p><h1>${escape(c.title)}</h1>${badge(c)}<p class="lead">${escape(c.purpose)}</p><div class="tabs" role="tablist" aria-label="Component views">${tabs.map(t => `<button role="tab" aria-selected="${t === tab}" data-tab="${t}">${t}</button>`).join('')}</div><div class="panel" role="tabpanel">${content[tab]}</div></section>`;
  for (const button of app.querySelectorAll('[data-tab]')) button.onclick = () => { component(c, button.dataset.tab); app.querySelector(`[data-tab="${button.dataset.tab}"]`).focus(); };
}
let lastResult;
function download(value, filename) { const href = URL.createObjectURL(new Blob([JSON.stringify(value, null, 2)], { type:'application/json' })); const a = document.createElement('a'); a.href = href; a.download = filename; a.click(); setTimeout(() => URL.revokeObjectURL(href), 1000); }
function renderComparison(result) {
  const arms = Object.values(result.arms), max = Math.max(...arms.map(a => a.bytes), 1);
  return `<h3>Complete serialized input work</h3>${arms.map(a => `<div class="bar"><span>${a.id}</span><div class="track"><div class="fill" style="width:${100 * a.bytes / max}%"></div></div><b>${a.bytes.toLocaleString()} B</b></div>`).join('')}<div class="scroll"><table><thead><tr><th>Arm</th><th>Input bytes</th><th>Reduction vs full</th><th>Exact fixture facts</th><th>Dispatch</th></tr></thead><tbody>${arms.map(a => `<tr><td>${a.id}</td><td>${a.bytes}</td><td>${a.noDispatch ? 'Failed arm' : `${(100 * reductionRatio(result.arms.full.bytes, a.bytes).value).toFixed(1)}%`}</td><td>${a.exactFactRecall == null ? 'Unavailable' : `${Math.round(a.exactFactRecall * 100)}%`}</td><td>${a.status}</td></tr>`).join('')}</tbody></table></div><p class="notice">Exact fixture facts means required source spans present in packets. It does not score generated answers. The combined arm counts repeated shared pins and routing overhead. A failed dispatch cannot substantiate an efficiency gain.</p><details><summary>Inspect source packets and accounting</summary><pre>${escape(JSON.stringify(result, null, 2))}</pre></details>`;
}
function lab() {
  app.innerHTML = `<section class="section"><div class="eyebrow">EXECUTABLE REFERENCE / C02 + C03 + C27</div><h1>Carry the evidence.<br>Keep the archive.</h1><span class="badge">FIXTURE · synthetic data · no live calls</span><p class="lead">Compare a full-context baseline, a recent tail, lexical retrieval, sparse exact packing and a combined worker route on the same synthetic history.</p><div class="panel"><div class="controls"><label>History milestones<input id="size" type="number" min="8" max="1024" value="64"></label><label>Packet budget / bytes<input id="budget" type="number" min="100" max="1000000" value="6000"></label><label>Retrieval records<input id="retrieval" type="number" min="0" max="1000" value="12"></label><label>Combined workers<select id="workers"><option>1</option><option>2</option><option selected>4</option><option>8</option></select></label></div><div class="actions"><button id="run">Run comparison</button><button id="overflow">Inject pinned overflow</button><button id="export" disabled>Export sanitized run</button></div><div id="result" aria-live="polite">Run the same declared fixture across all five arms.</div></div><p>Binding: deterministic browser JavaScript. Data: generated public-safe project history. Accounting: UTF-8 JSON transport bytes, including packet headers. Model token usage, live latency, cost and semantic quality: unavailable.</p></section>`;
  const execute = async overflow => {
    const out = document.querySelector('#result'), button = document.querySelector('#run'); button.disabled = true;
    try { lastResult = await runComparison({ historySize:+document.querySelector('#size').value, budgetBytes:overflow ? 100 : +document.querySelector('#budget').value, retrievalLimit:+document.querySelector('#retrieval').value, workers:+document.querySelector('#workers').value }); out.innerHTML = renderComparison(lastResult); document.querySelector('#export').disabled = false; }
    catch (error) { out.textContent = `Comparison failed: ${error.message}`; lastResult = null; document.querySelector('#export').disabled = true; }
    finally { button.disabled = false; }
  };
  document.querySelector('#run').onclick = () => execute(false); document.querySelector('#overflow').onclick = () => execute(true); document.querySelector('#export').onclick = () => download(lastResult, 'synthetic-context-run.json');
}
function evidencePage() {
  app.innerHTML = `<section class="section"><div class="eyebrow">REPRODUCIBLE EVIDENCE</div><h1>Inspect the claim.<br>Recompute the result.</h1><p class="lead">Deterministic tests establish local mechanism behavior and metric arithmetic. Measured model comparisons need their own experiment.</p><div class="metrics"><div><b>${evidence?.tests?.passed ?? '—'}</b><span>Executed tests passed</span></div><div><b>${components.length}</b><span>Documented components</span></div><div><b>${components.reduce((s,c) => s + c.metrics.length,0)}</b><span>Specified metric endpoints</span></div><div><b>0</b><span>Provider calls in fixture suite</span></div></div>${evidence?.comparison ? renderComparison(evidence.comparison) : '<p class="notice">Benchmark bundle unavailable.</p>'}<h2>Statistics with declared inputs</h2><p>Seeded paired bootstrap, MATTR, repeated trigram rate, sentence-length variation and lexical Jensen–Shannon divergence have deterministic reference vectors. These calculations do not establish Headspace model or human outcomes.</p><pre>${escape(JSON.stringify(evidence?.statistics ?? { status:'Unavailable' }, null, 2))}</pre><h2>Component evidence matrix</h2><div class="scroll"><table><thead><tr><th>Component</th><th>Reference mechanism</th><th>Default-model comparison</th><th>Metric endpoints</th></tr></thead><tbody>${components.map(c => `<tr><td><a href="#/component/${c.id}">${c.id}</a> ${escape(c.title)}</td><td>${escape(testsFor(c)?.mechanismStatus ?? 'Not tested')}</td><td>Unavailable</td><td>${c.metrics.length}</td></tr>`).join('')}</tbody></table></div><div class="actions"><a class="button" href="./data/results.json" download>Download results bundle</a><a class="button" href="./data/catalog.json" download>Download component contracts</a></div><p class="notice">The fixture matrix is a smoke suite, not a held-out population sample. Its uncertainty intervals describe its chosen configurations. Historical reports of 147 tests and 95.758% byte reduction are not reused as current results.</p></section>`;
}
function release() { app.innerHTML = `<section class="section"><div class="eyebrow">NOVACANENUMB / OPEN DESIGNS</div><h1>Build on the work.</h1><p class="lead">Context management, agent orchestration, constrained generation and native research form one design programme, with explicit interfaces and falsifiable experiments.</p>${publicConfig?.repositoryUrl ? `<a class="button" href="${escape(publicConfig.repositoryUrl)}">Open the source repository</a>` : '<p class="notice">Repository publication is pending. Local source, test commands and license are prepared.</p>'}${definition([['License','Novacanenumb Open Design License 1.0 permits use, modification and redistribution, including commercial use, with attribution. This is a custom license; no OSI certification is claimed.'],['Attribution','Architecture design programme: novacanenumb. Reference implementation and dossier: AI-assisted, with host integration and deterministic validation.'],['Reproduce','Node 22 or later. npm test; npm run benchmark; npm run verify; npm run preview. No API key required.'],['Implementation scope','Real sparse-context/archival reference mechanisms and statistical analytics. All 28 designs are documented; remaining mechanisms and native research are not completed here.'],['Supply boundary','The supplied separately licensed Hypervisor runtime is not redistributed in this repository. Original private documents and real conversation histories are excluded.']])}<a href="./LICENSE.txt" download>Read the custom license</a></section>`; }
function route() { const [, page, id] = location.hash.split('/'); if (page === 'component') component(components.find(c => c.id === id)); else if (page === 'lab') lab(); else if (page === 'evidence') evidencePage(); else if (page === 'release') release(); else home(); }
addEventListener('hashchange', route); route();
